"use client";

import { useEffect, useState } from "react";
import Image from "next/image";

type CardProps = {
  id: string;
  title: string;
  description?: string;
  imageUrl?: string;
  liked: boolean;
  role: "USER" | "ADMIN" | "CURATOR";

  category?: string;
  artist?: string;
  year?: number;

  onToggle: (id: string) => void;
};

export default function Card({
  id,
  title,
  description,
  imageUrl,
  liked,
  role,
  category,
  artist,
  year,
  onToggle,
}: CardProps) {
  const [open, setOpen] = useState(false);
  const [zoom, setZoom] = useState(1);

  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        setOpen(false);
        setZoom(1);
      }
    };

    window.addEventListener("keydown", handleKey);

    return () =>
      window.removeEventListener("keydown", handleKey);
  }, []);

  return (
    <>
      <div className="border rounded-lg p-4 shadow transition-all duration-200 hover:shadow-lg hover:-translate-y-1 relative">
        {imageUrl && (
          <div
            onClick={() => setOpen(true)}
            className="relative w-full h-48 bg-gray-100 rounded overflow-hidden cursor-pointer"
          >
            <Image
  src={imageUrl}
  alt={title}
  fill
  className="object-contain"
/>
          </div>
        )}

        <h2 className="font-bold mt-2">{title}</h2>

        {description && (
          <p className="text-sm text-gray-600">
            {description}
          </p>
        )}


        <div className="text-xs text-gray-500 mt-2 space-y-1">
          {category && <p> Style: {category}</p>}
          {artist && <p> Artist: {artist}</p>}
          {year && <p> Year: {year}</p>}
        </div>

        {role === "USER" && (
          <button
            onClick={() => onToggle(id)}
            className={`absolute top-2 right-2 text-2xl 
             transition-transform duration-200 hover:scale-125 active:scale-90 ${
               liked ? "text-red-500 scale-110" : "text-gray-400"
             }`}
          >
            {liked ? "❤️" : "🤍"}
          </button>
        )}
      </div>

      {open && imageUrl && (
        <div
          className="fixed inset-0 bg-black/80 flex items-center justify-center z-50 transition-opacity duration-200"
          onClick={() => {
            setOpen(false);
            setZoom(1);
          }}
        >
          <div
            onClick={(e) => e.stopPropagation()}
            className="relative w-[90vw] h-[90vh]"
          >
            <Image
              src={imageUrl}
              alt={title}
              fill
              className="object-contain rounded"
              style={{ transform: `scale(${zoom})` }}
            />
          </div>
        </div>
      )}
    </>
  );
}